const root = $json || {};
const envelope = root.body && typeof root.body === 'object' ? root.body : root;
const data = envelope.data && typeof envelope.data === 'object' ? envelope.data : (root.data || envelope);
const key = data.key || envelope.key || root.key || {};
const msg = data.message || envelope.message || root.message || {};

function onlyDigits(value) {
  return String(value || '').split('@')[0].replace(/\D/g, '');
}

function firstPhone(candidates) {
  for (const candidate of candidates) {
    const digits = onlyDigits(candidate);
    if (digits.length >= 10) return digits;
  }
  return '';
}

const remoteJid = String(
  key.remoteJid || key.remoteJidAlt || data.remoteJid || data.from || envelope.from || root.from || ''
).trim();
const phone = firstPhone([
  key.remoteJid, key.remoteJidAlt, data.remoteJid, data.number, envelope.number,
  root.number, data.phone, envelope.phone, root.phone, data.sender, envelope.sender, root.sender
]);
const text = String(
  data.text || envelope.text || root.text || data.bodyText || envelope.bodyText ||
  msg.conversation || msg.extendedTextMessage?.text || msg.imageMessage?.caption ||
  msg.videoMessage?.caption || msg.documentMessage?.caption ||
  msg.buttonsResponseMessage?.selectedDisplayText || msg.listResponseMessage?.title ||
  msg.templateButtonReplyMessage?.selectedDisplayText || ''
).trim();
const messageId = String(
  key.id || data.messageId || data.id || envelope.message_id || root.message_id ||
  root.messageId || root.id || ''
).trim() || `${phone || 'unknown'}:${Date.now()}`;
const fromMe = Boolean(key.fromMe || data.fromMe || envelope.fromMe || root.fromMe);
const messageType = String(data.messageType || envelope.messageType || root.messageType || '').trim();
const instance = String(envelope.instance || data.instance || root.instance || $env.EVOLUTION_INSTANCE_NAME || '').trim();
const isGroup = remoteJid.includes('@g.us');
const canReply = Boolean(phone && !fromMe && !isGroup);
const isSupportedText = Boolean(text);
return [{ json: {
  phone,
  remote_jid: remoteJid,
  message_text: text,
  message_id: messageId,
  message_type: messageType,
  push_name: data.pushName || envelope.pushName || root.pushName || data.push_name || envelope.push_name || '',
  instance,
  from_me: fromMe,
  is_group: isGroup,
  can_reply: canReply,
  is_supported_text: isSupportedText,
  is_valid_user_message: Boolean(canReply && isSupportedText),
  current_date: new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }),
  current_datetime: new Date().toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo', hour12: false }).replace(' ', 'T'),
  raw: root
} }];

function cleanJsonContent(value) {
  if (value && typeof value === 'object') return value;
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withoutFence = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  const first = withoutFence.indexOf('{');
  const last = withoutFence.lastIndexOf('}');
  if (first >= 0 && last > first) return withoutFence.slice(first, last + 1);
  return withoutFence;
}
const content = $json.output ?? $json.text ?? $json.response ?? $json.choices?.[0]?.message?.content ?? '';
let parsed;
try {
  const cleaned = cleanJsonContent(content);
  parsed = typeof cleaned === 'object' ? cleaned : JSON.parse(cleaned);
} catch (error) {
  parsed = {
    intent: 'help',
    confidence: 0,
    needs_clarification: false,
    reply_text: 'Posso te ajudar com finanças mensais fora do cartão: lançar conta, listar entradas/saídas, marcar como paga, corrigir ou apagar. Ex.: lançar aluguel de R$ 2.500 para junho. 😉'
  };
}
if (!parsed || typeof parsed !== 'object') parsed = { intent: 'help', reply_text: 'Me manda o que você quer fazer nas finanças mensais fora do cartão.' };
const apiIntents = new Set(['create_monthly_finance','list_monthly_finances','mark_finance_paid','mark_finance_unpaid','update_monthly_finance','delete_monthly_finance']);
parsed.should_call_api = apiIntents.has(String(parsed.intent || '')) && parsed.needs_clarification !== true;
if (parsed.needs_clarification === true && !parsed.clarifying_question) parsed.clarifying_question = 'Me dá mais um detalhe para eu não lançar essa conta no mês errado?';
if (['greeting','help'].includes(String(parsed.intent || '')) && !parsed.reply_text) {
  parsed.reply_text = 'Oi! Aqui é seu concierge das finanças mensais do AcerttaPay. Posso lançar contas fora do cartão, listar o mês, marcar como paga, corrigir ou apagar. Ex.: *lançar aluguel de R$ 2.500 para junho*. 📒';
}
if (String(parsed.intent || '') === 'out_of_scope' && !parsed.reply_text) parsed.reply_text = 'Essa parece compra de cartão. Para isso, usa o fluxo de Compra Assistida. Aqui eu cuido das contas e entradas fora do cartão. 😉';
return [{ json: parsed }];

const parsed = $json || {};
const intent = String(parsed.intent || '').trim();
const phone = $('Normalize Evolution Payload').first().json.phone;
const source = {
  channel: 'whatsapp',
  instance: $('Normalize Evolution Payload').first().json.instance,
  message_id: $('Normalize Evolution Payload').first().json.message_id,
  raw_text: $('Normalize Evolution Payload').first().json.message_text
};
const query = parsed.query || {};
const finance = parsed.finance || {};
const target = parsed.target || {};
const patch = parsed.patch || {};
let endpoint = '/api/automation/v1/monthly-finances/search';
let body = { phone, source, query };
let idempotencySuffix = intent;
function cleanId(value) {
  return String(value || '0').replace(/[^0-9]/g, '') || '0';
}
function targetId() {
  return cleanId(target.finance_id || target.id || parsed.finance_id || parsed.id);
}
if (intent === 'list_monthly_finances') {
  endpoint = '/api/automation/v1/monthly-finances/search';
} else if (intent === 'create_monthly_finance') {
  endpoint = '/api/automation/v1/monthly-finances';
  body.finance = finance;
  idempotencySuffix += ':' + (finance.description || 'nova');
} else if (intent === 'mark_finance_paid') {
  const id = targetId();
  endpoint = `/api/automation/v1/monthly-finances/${id}/mark-paid`;
  body.query = { ...query, finance_hint: target.finance_hint || query.finance_hint || finance.description || null };
  idempotencySuffix += ':' + id + ':' + (target.finance_hint || query.finance_hint || 'hint');
} else if (intent === 'mark_finance_unpaid') {
  const id = targetId();
  endpoint = `/api/automation/v1/monthly-finances/${id}/mark-unpaid`;
  body.query = { ...query, finance_hint: target.finance_hint || query.finance_hint || finance.description || null };
  idempotencySuffix += ':' + id + ':' + (target.finance_hint || query.finance_hint || 'hint');
} else if (intent === 'update_monthly_finance') {
  const id = targetId();
  endpoint = `/api/automation/v1/monthly-finances/${id}/update`;
  body.query = { ...query, finance_hint: target.finance_hint || query.finance_hint || finance.description || null };
  body.patch = patch;
  idempotencySuffix += ':' + id + ':' + (target.finance_hint || query.finance_hint || 'hint');
} else if (intent === 'delete_monthly_finance') {
  const id = targetId();
  endpoint = `/api/automation/v1/monthly-finances/${id}/delete`;
  body.query = { ...query, finance_hint: target.finance_hint || query.finance_hint || finance.description || null };
  idempotencySuffix += ':' + id + ':' + (target.finance_hint || query.finance_hint || 'hint');
}
return [{ json: { intent, endpoint, body, idempotency_key: `whatsapp-monthly-finance:${$('Normalize Evolution Payload').first().json.instance}:${$('Normalize Evolution Payload').first().json.message_id}:${idempotencySuffix}` } }];

const result = $json || {};
let text = result.whatsapp?.text || result.message || result.reply_text || '';
if (!text) text = 'Finanças mensais processadas no AcerttaPay, mas a resposta veio tímida. Tenta de novo em instantes.';
return [{ json: { ...result, outbound_text: text } }];

const phone = $('Normalize Evolution Payload').first().json.phone;
const source = {
  channel: 'whatsapp',
  instance: $('Normalize Evolution Payload').first().json.instance,
  message_id: $('Normalize Evolution Payload').first().json.message_id,
  raw_text: $('Normalize Evolution Payload').first().json.message_text
};
return [{ json: {
  endpoint: '/api/automation/v1/monthly-finances/conversations/reply',
  idempotency_key: `whatsapp-monthly-finance-reply:${$('Normalize Evolution Payload').first().json.instance}:${$('Normalize Evolution Payload').first().json.message_id}`,
  body: { phone, source, reply: { raw_text: $('Normalize Evolution Payload').first().json.message_text } }
} }];
